function relation(subject, predicate, object, polarity, explanation) {
  return { subject, predicate, object, polarity, explanation };
}
function uniqueSurface(values) {
  const seen = new Set();
  const result = [];
  for (const value of values) {
    const text = String(value ?? "").trim();
    const key = text.toLocaleLowerCase().replace(/[^\p{L}\p{N}]+/gu, " ").trim();
    if (!text || seen.has(key)) continue;
    seen.add(key);
    result.push(text);
  }
  return result;
}

function K(batch, id, canonicalSignal, kind, semanticFamily, relatedDomains, labels, definition, positiveClues, negativeClues, options = {}) {
  if (canonicalSignal && !canonicalSignals.has(canonicalSignal)) {
    throw new Error(`Unknown canonical signal for ${id}: ${canonicalSignal}`);
  }
  const card = {
    schemaVersion: SCHEMA,
    id: `concept.${id}`,
    status: "validated",
    kind,
    labels,
    ...(canonicalSignal ? { canonicalSignal } : {}),
    semanticFamily,
    relatedDomains,
    definition,
    positiveClues,
    negativeClues,
    compatibleTypes: options.compatibleTypes ?? defaultTypes[kind] ?? ["string"],
    relations: options.relations ?? [],
    requiredEvidence: options.requiredEvidence ?? [`${kind}_shape`, "contextual_compatibility"],
    blockers: options.blockers ?? [],
    analysisClass: options.analysisClass ?? (canonicalSignal ? "descriptive_or_canonical_bridge" : "descriptive"),
    ...(options.formula ? { formula: options.formula } : {}),
    provenance: {
      sourceType: options.sourceType ?? "model_synthesis",
      sourceLabel: options.sourceLabel ?? "GPT-5.6 Sol foundational business knowledge synthesis",
      synthesizedAt: SYNTHESIZED_AT,
      notes: options.notes ?? ["General reusable business knowledge; not fixture-specific truth."],
    },
  };
  const list = batches.get(batch) ?? [];
  list.push(card);
  batches.set(batch, list);
  return card;
}

