const allCards = [...batches.values()].flat();
const byId = new Map(allCards.map((card) => [card.id, card]));
for (const [leftId, rightId, explanation] of CONFUSIONS) {
  const left = byId.get(leftId);
  const right = byId.get(rightId);
  if (!left || !right) throw new Error(`Confusion edge references missing card: ${leftId} <> ${rightId}`);
  left.relations.push(relation(leftId, "distinct_from", rightId, "distinct_from", explanation));
  right.relations.push(relation(rightId, "distinct_from", leftId, "distinct_from", explanation));
}
for (const card of allCards) {
  if (!card.formula) continue;
  for (const input of card.formula.requiredInputs) {
    card.relations.push(relation(card.id, "requires_input", input, "requires", `Formula ${card.id} requires explicit evidence for ${input}.`));
  }
}

fs.mkdirSync(KNOWLEDGE_DIR, { recursive: true });
const files = [];
for (const [batchName, cards] of [...batches.entries()].sort(([a], [b]) => a.localeCompare(b))) {
  cards.sort((a, b) => a.id.localeCompare(b.id));
  const fileName = `${batchName}.foundation.v1.json`;
  fs.writeFileSync(path.join(KNOWLEDGE_DIR, fileName), `${JSON.stringify(cards, null, 2)}\n`);
  files.push(fileName);
}

const bridgeCount = allCards.filter((card) => card.canonicalSignal).length;
const openConceptCount = allCards.length - bridgeCount;
const formulaCount = allCards.filter((card) => card.analysisClass === "guarded_formula").length;
const relationCount = allCards.reduce((sum, card) => sum + card.relations.length, 0);
const manifest = {
  schemaVersion: "lightbi.micro-brain.source-manifest.v1",
  corpusId: "lightbi.micro-brain.foundation",
  version: "0.2.0",
  maturityLabel: "registry_aligned_foundation_v1",
  maturityNote: "Foundation is aligned to every canonical signal exposed by the six supported runtime BA domains; this is semantic recall coverage, not a claim of metric authorization or complete business knowledge.",
  sourceStrategy: "model_synthesis_plus_registry_and_domain_contract_alignment",
  synthesizedAt: SYNTHESIZED_AT,
  files,
  counts: {
    cards: allCards.length,
    canonicalBridges: bridgeCount,
    openConcepts: openConceptCount,
    guardedFormulas: formulaCount,
    relations: relationCount,
    confusionPairs: CONFUSIONS.length,
    supportedRuntimeDomains: SUPPORTED_RUNTIME_BA_DOMAINS.length,
    registryCanonicalSignals: SEMANTIC_SIGNAL_REGISTRY_V1.length,
    registryAlignedCanonicalSignals: new Set(allCards.map((card) => card.canonicalSignal).filter(Boolean)).size,
  },
  invariants: [
    "retrieval_similarity_is_not_semantic_confidence",
    "canonical_bridge_requires_existing_registry_signal",
    "negative_knowledge_is_first_class",
    "unsupported_domain_recognition_does_not_activate_support",
    "fixture_specific_truth_is_forbidden",
  ],
};
fs.writeFileSync(path.join(KNOWLEDGE_DIR, "manifest.v1.json"), `${JSON.stringify(manifest, null, 2)}\n`);
console.log(JSON.stringify(manifest, null, 2));